import pandas as pd

def clean(df):
    d = df.copy()
    for c in d.select_dtypes(include=['object']).columns:
        d[c] = d[c].astype('string').str.strip()
    d['island'] = d['island'].replace({'Bisco': 'Biscoe'})
    for c in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if c in d.columns:
            d[c] = pd.to_numeric(d[c], errors='coerce')
    d = d.drop_duplicates()
    return d

def answer(df):
    d = clean(df)
    d = d[d['species'].notna()]
    out = d.groupby('species', dropna=True)['body_mass_g'].sum()
    return {str(k): float(v) for k, v in out.items()}
